export const BUILTIN_V2_BUNDLE = {"format":"od-builtin-bundle-v2","version":2,"generatedFrom":"core/knowledgecard/data-v2","hash":"c6d27168e98e2227e56949ef1a6f6736d9ea87c7c77d144a67953e04b908aa7f","files":[{"name":"92-animation-core.json","sha256":"6e90487be474043fe81ed7a57645a3c05c5058043826bfde0e0f62fa0259e5ab","text":"{\n  \"format\": \"od-knowledgecard\",\n  \"version\": 2,\n  \"entries\": [\n    {\n      \"id\": \"wb_anim_conventions\",\n      \"title\": \"动画规范·坐标/单位/颜色/读数（常驻）\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 动画绘制规范（常驻）\\n\\n## 你只写 drawFrame\\n- 位置只从 `state.<key>.x / .y` 读；不要重算运动、时间、速度。\\n- 不要写 `stateAt / VIEW / setup / readouts / STEPS / ANSWERS`；这些由程序生成。\\n- 不要写 `function drawFrame` 头、槽位标记或解释文字。\\n\\n## 坐标与尺寸\\n- 世界坐标：x 向右、y 向上、单位米；不要写像素、相机比例或 canvas 尺寸。\\n- 一屏画完：主体居中、留边距；视口由系统自动决定。\\n- 尺寸按画面需要，允许示意（物块画 1 m 也可以）；同题同类元件尽量同量级。\\n\\n## 画面\\n- 画布上不写任何文字：文字/公式标注、箭头 label、尺寸 text、坐标轴标签/单位都不显示；说明放画布外图例。\\n- 颜色由 `category` 决定；不要写 `color`。\\n- 虚线写 `{ dash: true }`；实线不写；只有自定义间距才写 `[n, m]`。\\n- 不要画 v/a 箭头；运行时按程序里已有的刚体声明（`SIM.bodies`）自动求导绘制。\\n- 只有 `force / aux` 箭头才用 `Draw.arrow`，必须给 `category` 与 `mag`（真实量级），不要给 `scale / color`。\\n\\n## 静止物体\\n- 地面/斜面/轨道按读题几何或题图摆；尽量穿过运动元件在 t=0 附近的位置；绳/杆连到实际端点；允许示意，不要悬空。\\n- 静止基准只画一次，不要逐帧换位置。\\n\\n## 自检\\n- [ ] 没有 `stateAt / VIEW / setup / readouts` / 槽位标记；可以读 `context.at(t)`，不要写 `context`。\\n- [ ] 没有像素、没有文字、没有 v/a 箭头。\\n- [ ] 运动位置都来自 `state.<key>`；静止几何没有悬空。\",\n      \"order\": 1,\n      \"priority\": \"high\",\n      \"code_examples\": [],\n      \"kind\": \"anim_rule\",\n      \"constant\": true\n    },\n    {\n      \"id\": \"wb_anim_stages\",\n      \"title\": \"动画规范·阶段表与状态组织（常驻）\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 多段运动与多物体（常驻）\\n\\n## 什么时候用\\n- 题目有多个运动阶段，或同时有多个会动物体。\\n\\n## 画法\\n- 每个会动物体在 `state` 里有一个 key（`block_A / ball_A / …`）；位置只从 `state.<key>.x / .y` 读。\\n- 阶段边界用**世界坐标**的细虚线或几何标记标出（数值从 analysis 表读，写死为常量），不写文字。\\n- 同一元件的相邻段在边界处位置必须连续；不要让物体瞬移。\\n- 多个物体各自更新，不要用同一个 key 画两个物体。\\n\\n## 自检\\n- [ ] 每个会动物体都有自己的 state key。\\n- [ ] 边界标记用固定坐标，不跟着物体漂移。\\n- [ ] 没有 `stateAt / STEPS / SIM.bodies / setup`。\",\n      \"order\": 2,\n      \"priority\": \"high\",\n      \"code_examples\": [],\n      \"kind\": \"anim_rule\",\n      \"constant\": true\n    }\n  ]\n}\n"},{"name":"93-elements.json","sha256":"58b2c928c9e9170502af664c9f6da812f33cefa49ba11c24730bea561832931f","text":"{\n  \"format\": \"od-knowledgecard\",\n  \"version\": 2,\n  \"entries\": [\n    {\n      \"id\": \"wb_el_block\",\n      \"title\": \"元件·物块 / 滑块\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 元件·物块 / 滑块\\n\\n## 判据\\n题面或配图里出现「物块」「滑块」这类东西时画这一件。\\n\\n## 状态字段\\n- `state.<key>.angleDeg` 由运行时按速度方向注入；没有速度时由场景卡给静态角。\\n- `state.<key>.x / .y` 是元件**质心**；不需要再偏移。\\n- 不要写 `stateAt` / `VIEW` / `setup` / `readouts`。\\n\\n## 画法\\n- `Draw.box([state.block_A.x, state.block_A.y], 0.4, 0.3, { angleDeg: state.block_A.angleDeg });`\\n\\n## 这条元件最常错的地方\\n方块中心直接画在 `state.x / state.y` 上；方案二不承诺贴面，允许示意。\\n\\n## 自检\\n- [ ] 用 `state.<key>.x / .y` 定位置（质心）；尺寸自己定，给个数就行。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 静止物体按读题几何摆放，没有悬空。\",\n      \"order\": 900,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.box([state.block_A.x, state.block_A.y], 0.4, 0.3, { angleDeg: state.block_A.angleDeg });\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"block\"\n      ],\n      \"size\": {\n        \"shape\": \"box\",\n        \"rotatable\": true\n      },\n      \"physical\": {\n        \"w\": 0.2,\n        \"h\": 0.1\n      }\n    },\n    {\n      \"id\": \"wb_el_board\",\n      \"title\": \"元件·长木板 / 小车\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 元件·长木板 / 小车\\n\\n## 判据\\n题面或配图里出现「长木板」「平板」「车板」「小车」这类东西时画这一件；小车不画轮子，用矩形示意即可。\\n\\n## 状态字段\\n- `state.<key>.angleDeg` 由运行时按速度方向注入；没有速度时由场景卡给静态角。\\n- `state.<key>.x / .y` 是元件**质心**；不需要再偏移。\\n- 不要写 `stateAt` / `VIEW` / `setup` / `readouts`。\\n\\n## 画法\\n- `Draw.box([state.board_A.x, state.board_A.y], 3.0, 0.1, { angleDeg: state.board_A.angleDeg });`（3.0 换成画面需要的板长，米，可示意）\\n\\n## 这条元件最常错的地方\\n把板长写死成与题面完全无关、又小到看不见的数（板长按画面需要，米，可示意）\\n\\n## 自检\\n- [ ] 板厚不写死；板长按画面需要给（米，可示意）。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 静止物体按读题几何摆放，没有悬空。\",\n      \"order\": 901,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.box([state.board_A.x, state.board_A.y], 3.0, 0.1, { angleDeg: state.board_A.angleDeg });\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"board\"\n      ],\n      \"size\": {\n        \"shape\": \"box\",\n        \"rotatable\": true\n      },\n      \"physical\": {\n        \"h\": 0.02\n      }\n    },\n    {\n      \"id\": \"wb_el_ball\",\n      \"title\": \"元件·小球 / 质点 / 卫星\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 元件·小球 / 质点 / 卫星\\n\\n## 判据\\n题面或配图里出现「小球」「质点」「卫星」这类东西时画这一件；质点和卫星按题目语义可以画成小球，也可以画成小物块。\\n\\n## 状态字段\\n- `state.<key>.x / .y` 是元件**质心**；不需要再偏移。\\n- 不要写 `stateAt` / `VIEW` / `setup` / `readouts`。\\n\\n## 画法\\n- 小球/质点（圆形）：`Draw.circle([state.ball_A.x, state.ball_A.y], 0.16);`\\n- 质点按题意当物块（方形）：`Draw.box([state.ball_A.x, state.ball_A.y], 0.4, 0.3);`\\n\\n## 这条元件最常错的地方\\n质点一律画成大圆；或反过来把小球画成方块。按题目语义选 `circle` 或 `box`，不要自造 SDK 里没有的函数名。\\n\\n## 自检\\n- [ ] 用 `state.<key>.x / .y` 定位置（质心）；半径/宽高自己定。\\n- [ ] 卫星只画本体，椭圆轨道归 `celestial_orbit` 场景。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 静止物体按读题几何摆放，没有悬空。\",\n      \"order\": 904,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.circle([state.ball_A.x, state.ball_A.y], 0.16);\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"ball\"\n      ],\n      \"size\": {\n        \"shape\": \"circle\",\n        \"rotatable\": false\n      },\n      \"physical\": {\n        \"w\": 0.1,\n        \"h\": 0.1,\n        \"r\": 0.05\n      }\n    },\n    {\n      \"id\": \"wb_el_spring\",\n      \"title\": \"元件·弹簧\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 元件·弹簧（连接件）\\n\\n## 判据\\n题面或配图里出现「弹簧」这类东西时画这一件；它通常只是连接件。\\n\\n## 状态字段\\n- 两端各取一个端点：A 可以是 `state.<key>.x / .y`，也可以是世界坐标；B 同理。\\n- 两端都要更新；只接一端会让弹簧“斜穿”物体。\\n- 不要写 `stateAt` / `VIEW` / `setup` / `readouts`。\\n\\n## 画法\\n- `Draw.spring([0, 1.8], [state.spring_A.x, state.spring_A.y], { coils: 12 });`\\n\\n## 这条元件最常错的地方\\n两端各写一套来源；只更新活动端；把弹簧当成有质量的振子。\\n\\n## 自检\\n- [ ] 两端都来自实际端点，没有悬空。\\n- [ ] 没有给弹簧硬造独立 state。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 906,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.spring([0, 1.8], [state.spring_A.x, state.spring_A.y], { coils: 12 });\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"spring\"\n      ],\n      \"size\": {\n        \"shape\": \"point\",\n        \"rotatable\": false\n      }\n    },\n    {\n      \"id\": \"wb_el_rope\",\n      \"title\": \"元件·绳 / 细线\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 元件·绳 / 细线（连接件）\\n\\n## 判据\\n题面或配图里出现「绳」「细线」这类东西时画这一件；它通常只是连接件。\\n\\n## 状态字段\\n- 两端各取一个端点：A / B 都可以是 `state.<key>.x / .y` 或世界坐标。\\n- 不要写 `stateAt` / `VIEW` / `setup` / `readouts`。\\n\\n## 画法\\n- `Draw.line([0, 1.8], [state.rope_A.x, state.rope_A.y]);`\\n\\n## 这条元件最常错的地方\\n只接一端；绳松弛时仍硬拉成直线（没有松弛量就画直绳，并承认这是示意）。\\n\\n## 自检\\n- [ ] 两端都来自实际端点，没有悬空。\\n- [ ] 没有硬造独立 state。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 908,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.line([0, 1.8], [state.rope_A.x, state.rope_A.y]);\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"rope\"\n      ],\n      \"size\": {\n        \"shape\": \"point\",\n        \"rotatable\": false\n      }\n    },\n    {\n      \"id\": \"wb_el_trace_path\",\n      \"title\": \"元件·轨迹\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 元件·轨迹（跟随件）\\n\\n## 判据\\n题面或配图里出现「轨迹」这类东西时画这一件；它不独立触发，必须跟随一个运动元件。\\n\\n## 状态字段\\n- 目标元件的 `state.<key>.x / .y` 是采样点；没有目标就不画。\\n- 用 `context.at(tt)` 采样历史，只画到当前 `t` 为止；不要画“还没发生”的时段。\\n\\n## 画法\\n- `Draw.trace([[0, 0], [state.trace_path_A.x, state.trace_path_A.y]]);`\\n\\n## 这条元件最常错的地方\\n另写一条解析曲线当轨迹；没有目标还硬画；把未来时段也画出来。\\n\\n## 自检\\n- [ ] 轨迹跟随一个真实运动元件。\\n- [ ] 只画到当前 `t`，没有未来时段。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 919,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.trace([[0, 0], [state.trace_path_A.x, state.trace_path_A.y]]);\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"trace_path\"\n      ],\n      \"size\": {\n        \"shape\": \"point\",\n        \"rotatable\": false\n      }\n    },\n    {\n      \"id\": \"wb_el_graph_wave\",\n      \"title\": \"元件·波形 / 连续曲线\",\n      \"origin\": \"builtin\",\n      \"enabled\": false,\n      \"content\": \"# 元件·波形 / 连续曲线\\n\\n## 判据\\n题面或配图里出现「波形」「连续曲线」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；按读题几何用世界坐标画。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`。\\n\\n## 画法\\n- `Draw.curve([[0, 0], [0.5, 0.3], [1, 0], [1.5, -0.3]]);`\\n\\n## 这条元件最常错的地方\\n采样点太少（折线感）；波形平移用重画新线而不是整条平移\\n\\n## 自检\\n- [ ] 静止几何用世界坐标，不跟 `state` 漂移。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 需要读 state 时才用 `state.<key>.x / .y`，没有 `stateAt / VIEW / setup / readouts`；可以读 `context.at(t)`。\",\n      \"order\": 924,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.curve([[0, 0], [0.5, 0.3], [1, 0], [1.5, -0.3]]);\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"graph_wave\"\n      ],\n      \"size\": {\n        \"shape\": \"curve\",\n        \"rotatable\": false\n      }\n    },\n    {\n      \"id\": \"wb_sc_ground\",\n      \"title\": \"场景·地面 / 墙面（斜线阴影）\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·地面 / 墙面（斜线阴影）\\n\\n## 判据\\n题面或配图里出现「地面」「墙面」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；按读题几何用世界坐标画。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`。\\n\\n## 画法\\n- `Draw.ground(-1.5, 2.5);`\\n\\n## 这条元件最常错的地方\\n`Draw.incline` 自带阴影底面，再叠一层 ground 会出现双阴影\\n\\n## 自检\\n- [ ] 静止几何用世界坐标，不跟 `state` 漂移。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 需要读 state 时才用 `state.<key>.x / .y`，没有 `stateAt / VIEW / setup / readouts`；可以读 `context.at(t)`。\",\n      \"order\": 903,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.ground(-1.5, 2.5);\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"ground\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_incline\",\n      \"title\": \"场景·斜面 / 斜坡\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·斜面 / 斜坡\\n\\n## 判据\\n题面或配图里出现「斜面」「斜坡」「斜面体」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；顶点、倾角、沿面长度由场景卡或题面给定。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`；静止时不要读 state。\\n- 斜面画到物块下方/接触处即可：先读 `state.<key>.x / .y`（质心），坡面贴着物块下沿；允许示意。\\n\\n## 画法\\n- `Draw.incline([0, 0.6], { angleDeg: 30, length: 1.2 });`\\n\\n## 这条元件最常错的地方\\n顶点不是最高点；`angleDeg` 正负反了；斜面离物块太远/悬空。\\n\\n## 自检\\n- [ ] 顶点是最高点，坡脚方向与 `angleDeg` 正负一致。\\n- [ ] 坡面画到物块下方/接触处（允许示意）。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 902,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.incline([0, 0.6], { angleDeg: 30, length: 1.2 });\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"incline\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_belt\",\n      \"title\": \"场景·传送带 / 履带\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·传送带 / 履带\\n\\n## 判据\\n题面或配图里出现「传送带」「履带」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；端点写**带面顶**（米），本地会把带体画在端点下方。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`；静止时不要读 state。\\n- 放在带上的物体，带面顶的 `y` 尽量接近物块 `state.<key>.y`；允许示意。\\n- 需要让带看起来在动时，用 `tickPhase` 随时间平移；不要改带面位置。\\n\\n## 画法\\n- `Draw.belt([0, 0.2], [4, 0.2], { r: 0.05, ticks: 16, tickPhase: t * 1.5 });`\\n\\n## 这条元件最常错的地方\\n带面顶的 `y` 与物块 `y` 差太远；`tickPhase` 不随时间变，带看起来不动。\\n\\n## 自检\\n- [ ] 带面顶的 `y` 接近物块 `y`（允许示意）。\\n- [ ] 没有读 `state`；位置用物理米 `x/y`，尺寸用米，画布上不写字。\\n- [ ] 需要动画时只改 `tickPhase`，不改带面位置。\",\n      \"order\": 911,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.belt([0, 0.2], [4, 0.2], { r: 0.05, ticks: 16, tickPhase: t * 1.5 });\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"belt\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_arc_track\",\n      \"title\": \"场景·圆弧轨道 / 拱桥\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·圆弧轨道 / 拱桥\\n\\n## 判据\\n题面或配图里出现「圆弧轨道」「拱桥」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；按读题几何用世界坐标画。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`。\\n\\n## 画法\\n- `Draw.arc([0, 0], 0.8, -90, 90);`\\n\\n## 这条元件最常错的地方\\n`Draw.arc` 的角度是**角度制、逆时针为正**，别塞弧度\\n\\n## 自检\\n- [ ] 静止几何用世界坐标，不跟 `state` 漂移。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 需要读 state 时才用 `state.<key>.x / .y`，没有 `stateAt / VIEW / setup / readouts`；可以读 `context.at(t)`。\",\n      \"order\": 905,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.arc([0, 0], 0.8, -90, 90);\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"arc_track\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_pulley\",\n      \"title\": \"场景·滑轮\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·滑轮\\n\\n## 判据\\n题面或配图里出现「滑轮」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；按读题几何用世界坐标画。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`。\\n\\n## 画法\\n- `Draw.pulley([0, 2.4], 0.2);`\\n\\n## 这条元件最常错的地方\\n过滑轮的绳要画成**两段**，切点离圆心距离 = r\\n\\n## 自检\\n- [ ] 静止几何用世界坐标，不跟 `state` 漂移。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 需要读 state 时才用 `state.<key>.x / .y`，没有 `stateAt / VIEW / setup / readouts`；可以读 `context.at(t)`。\",\n      \"order\": 907,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.pulley([0, 2.4], 0.2);\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"pulley\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_plates\",\n      \"title\": \"场景·平行板 / 极板\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·平行板 / 极板\\n\\n## 判据\\n题面或配图里出现「平行板」「极板」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；按读题几何用世界坐标画。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`。\\n\\n## 画法\\n- `Draw.line([-1, 1.6], [3, 1.6], { width: 3 });`\\n- `Draw.line([-1, 0.4], [3, 0.4], { width: 3 });`\\n\\n## 这条元件最常错的地方\\n板间画场区符号，板外不画场区符号\\n\\n## 自检\\n- [ ] 静止几何用世界坐标，不跟 `state` 漂移。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 需要读 state 时才用 `state.<key>.x / .y`，没有 `stateAt / VIEW / setup / readouts`；可以读 `context.at(t)`。\",\n      \"order\": 913,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.line([-1, 1.6], [3, 1.6], { width: 3 });\\nDraw.line([-1, 0.4], [3, 0.4], { width: 3 });\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"plates\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_ray\",\n      \"title\": \"场景·光线\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·光线\\n\\n## 判据\\n题面或配图里出现「光线」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；按读题几何用世界坐标画。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`。\\n\\n## 画法\\n- `Draw.ray([-1, 0.8], [0, 0.8]);`\\n\\n## 这条元件最常错的地方\\n全反射时仍画一条\\\"淡淡的折射光\\\"（超过临界角就没有折射段）\\n\\n## 自检\\n- [ ] 静止几何用世界坐标，不跟 `state` 漂移。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 需要读 state 时才用 `state.<key>.x / .y`，没有 `stateAt / VIEW / setup / readouts`；可以读 `context.at(t)`。\",\n      \"order\": 915,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.ray([-1, 0.8], [0, 0.8]);\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"ray\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_lens\",\n      \"title\": \"场景·透镜\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·透镜\\n\\n## 判据\\n题面或配图里出现「透镜」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；按读题几何用世界坐标画。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`。\\n\\n## 画法\\n- `Draw.lens([1, 0.8], { height: 1.2, focal: 0.5 });`\\n\\n## 这条元件最常错的地方\\n`height` 与 `focal` 是必填（都是几何量），缺一个直接抛错\\n\\n## 自检\\n- [ ] 静止几何用世界坐标，不跟 `state` 漂移。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 需要读 state 时才用 `state.<key>.x / .y`，没有 `stateAt / VIEW / setup / readouts`；可以读 `context.at(t)`。\",\n      \"order\": 916,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.lens([1, 0.8], { height: 1.2, focal: 0.5 });\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"lens\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_light_spot\",\n      \"title\": \"场景·光斑 / 照射区域\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·光斑 / 照射区域\\n\\n## 判据\\n题面或配图里出现「光斑」「照射区域」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；按读题几何用世界坐标画。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`。\\n\\n## 画法\\n- `Draw.polygon([[1.4, 0.2], [1.6, 0.26], [1.6, 0.14]], { fill: 'rgba(90,150,255,0.25)' });`\\n\\n## 这条元件最常错的地方\\n`polygon` 的 `fill` 是**颜色字符串**（`chart` 的 `fill` 才是开关 `true`）\\n\\n## 自检\\n- [ ] 静止几何用世界坐标，不跟 `state` 漂移。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 需要读 state 时才用 `state.<key>.x / .y`，没有 `stateAt / VIEW / setup / readouts`；可以读 `context.at(t)`。\",\n      \"order\": 917,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.polygon([[1.4, 0.2], [1.6, 0.26], [1.6, 0.14]], { fill: 'rgba(90,150,255,0.25)' });\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"light_spot\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_axis_box\",\n      \"title\": \"场景·坐标轴框（v–t / p–V）\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·坐标轴框（v–t / p–V）\\n\\n## 判据\\n题面或配图里出现「坐标轴框」这类东西时画这一件。\\n\\n## 状态字段\\n- 本元件通常静止，不需要 `state`；按读题几何用世界坐标画。\\n- 若读题判定它也会动，才按 user 消息的映射读 `state.<key>.x / .y`。\\n\\n## 画法\\n- `Draw.axisBox([-0.2, -0.2], 2.4, 4.4);`\\n\\n## 这条元件最常错的地方\\n轴框里写字母/单位；量程盖不住数据（点跑出框外）\\n\\n## 自检\\n- [ ] 静止几何用世界坐标，不跟 `state` 漂移。\\n- [ ] 位置用物理米 `x/y`，尺寸自己定（米），没有像素；画布上不写字。\\n- [ ] 需要读 state 时才用 `state.<key>.x / .y`，没有 `stateAt / VIEW / setup / readouts`；可以读 `context.at(t)`。\",\n      \"order\": 923,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.axisBox([-0.2, -0.2], 2.4, 4.4);\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"axis_box\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_rail\",\n      \"title\": \"场景·导轨 / 平行导轨\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·导轨 / 平行导轨\\n\\n## 判据\\n题面或配图里出现「导轨」「平行导轨」「金属导轨」这类东西时画这一件。\\n\\n## 布局\\n- 两条平行线，间距尽量接近题面给的导轨间距（允许示意）；导体棒两端尽量落在两条导轨上。\\n- 导轨是静态基准，不读 `state`；导轨上的导体棒由 `conductor_rod` 元件卡负责。\\n\\n## 画法\\n- `Draw.line([0, 0], [4, 0], { width: 3 });`\\n- `Draw.line([0, 0.4], [4, 0.4], { width: 3 });`\\n\\n## 这条场景最常错的地方\\n导轨间距与导体棒长度不匹配；把导轨画成会动的物体；导轨没接进电路。\\n\\n## 自检\\n- [ ] 两条导轨平行，间距与导体棒长度尽量一致（允许示意）。\\n- [ ] 导轨是静态基准，没有读 `state`。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 1000,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.line([0, 0], [4, 0], { width: 3 });\\nDraw.line([0, 0.4], [4, 0.4], { width: 3 });\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"rail\"\n      ]\n    },\n    {\n      \"id\": \"wb_el_conductor_rod\",\n      \"title\": \"元件·导体棒 / 金属棒\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 元件·导体棒 / 金属棒\\n\\n## 判据\\n题面或配图里出现「导体棒」「金属棒」这类东西时画这一件；导轨由 `rail` 场景卡负责。\\n\\n## 状态字段\\n- 用 `state.<key>.x / .y` 定棒的中心；棒长与方向由导轨/场景给。\\n- 不要写 `stateAt` / `VIEW` / `setup` / `readouts`。\\n\\n## 画法\\n- `Draw.line([state.conductor_rod_A.x - 0.5, state.conductor_rod_A.y], [state.conductor_rod_A.x + 0.5, state.conductor_rod_A.y], { width: 3 });`\\n\\n## 这条元件最常错的地方\\n把导轨也画进导体棒；棒长与导轨间距差太远；棒的两端没落在导轨附近。\\n\\n## 自检\\n- [ ] 只画棒，导轨交给 `rail` 场景。\\n- [ ] 棒长与导轨间距尽量一致，两端尽量落在导轨上（允许示意）。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 909,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.line([state.conductor_rod_A.x - 0.5, state.conductor_rod_A.y], [state.conductor_rod_A.x + 0.5, state.conductor_rod_A.y], { width: 3 });\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"conductor_rod\"\n      ],\n      \"size\": {\n        \"shape\": \"line\",\n        \"rotatable\": true\n      },\n      \"physical\": {\n        \"w\": 0.5,\n        \"h\": 0.02\n      }\n    },\n    {\n      \"id\": \"wb_el_light_rod\",\n      \"title\": \"元件·轻杆 / 细杆（连接件）\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 元件·轻杆 / 细杆（连接件）\\n\\n## 判据\\n题面或配图里出现「轻杆」「细杆」「直杆」这类东西时画这一件；它通常只是连接件，不拥有独立 `state`。\\n\\n## 状态字段\\n- 两端各取一个端点：可以是 `state.<key>.x / .y`，也可以是世界坐标。\\n- 两端都要更新；不要只挪一端。没有独立 state 时不要硬造。\\n\\n## 画法\\n- `Draw.line([0, 1.0], [state.light_rod_A.x, state.light_rod_A.y], { width: 3 });`\\n\\n## 这条元件最常错的地方\\n只接一端；把轻杆当成有质量的转动杆；杆的弹力方向当成“沿杆”。\\n\\n## 自检\\n- [ ] 两端都来自实际端点，没有悬空。\\n- [ ] 轻杆没有被当成独立运动体。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 909,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.line([0, 1.0], [state.light_rod_A.x, state.light_rod_A.y], { width: 3 });\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"light_rod\"\n      ],\n      \"size\": {\n        \"shape\": \"line\",\n        \"rotatable\": false\n      },\n      \"physical\": {\n        \"w\": 0.5,\n        \"h\": 0.02\n      }\n    },\n    {\n      \"id\": \"wb_sc_electric_field\",\n      \"title\": \"场景·匀强电场\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·匀强电场\\n\\n## 判据\\n题面或配图里出现「匀强电场」「电场」「偏转电场」这类东西时画这一件。\\n\\n## 布局\\n- 场区范围由场景给；电场方向用箭头表示，箭头方向就是正电荷受力方向。\\n- 平行板之间的电场归 `plates` 场景，本卡只画场本身。\\n\\n## 画法\\n- `Draw.arrow([0.4, 0.6], [0, 0.6], { category: 'aux', mag: 1 });`\\n- `Draw.arrow([1.2, 0.6], [0, 0.6], { category: 'aux', mag: 1 });`\\n\\n## 这条场景最常错的地方\\n把电场方向画成负电荷受力方向；场区越界；电场线穿过极板。\\n\\n## 自检\\n- [ ] 箭头方向是正电荷受力方向。\\n- [ ] 场区在极板之间，没有越界。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 914,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.arrow([0.4, 0.6], [0, 0.6], { category: 'aux', mag: 1 });\\nDraw.arrow([1.2, 0.6], [0, 0.6], { category: 'aux', mag: 1 });\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"electric_field\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_magnetic_field\",\n      \"title\": \"场景·匀强磁场\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·匀强磁场\\n\\n## 判据\\n题面或配图里出现「匀强磁场」「磁场」「磁感线」这类东西时画这一件。\\n\\n## 布局\\n- 场区范围由场景给；垂直世界向里用叉号，向外用点号。\\n- 边界磁场只在场区内铺阵列，不要铺满整屏。\\n\\n## 画法\\n- `Draw.fieldDots({ x: 0, y: 0, w: 2, h: 1.5 }, { symbol: 'cross', nx: 10, ny: 8 });`\\n\\n## 这条场景最常错的地方\\n叉/点方向反了；阵列溢出场区；把磁场边界画成实体墙。\\n\\n## 自检\\n- [ ] 叉号表示向里、点号表示向外。\\n- [ ] 阵列只在场区内。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 915,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.fieldDots({ x: 0, y: 0, w: 2, h: 1.5 }, { symbol: 'cross', nx: 10, ny: 8 });\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"magnetic_field\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_celestial_orbit\",\n      \"title\": \"场景·天体轨道\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·天体轨道\\n\\n## 判据\\n题面或配图里出现「卫星轨道」「椭圆轨道」「变轨」「双星」这类东西时画这一件。\\n\\n## 布局\\n- 中心天体在焦点；椭圆用 `Draw.ellipse` 画，半轴由场景给。\\n- 卫星本体由 `ball` 元件卡画，本卡只画轨道。\\n\\n## 画法\\n- `Draw.ellipse([0, 0], 1.2, 0.8);`\\n\\n## 这条场景最常错的地方\\n把椭圆画成圆；中心天体画在椭圆中心而不是焦点；轨道与卫星位置对不上。\\n\\n## 自检\\n- [ ] 椭圆半轴正确，中心天体在焦点。\\n- [ ] 卫星位置落在轨道上。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 926,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.ellipse([0, 0], 1.2, 0.8);\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"celestial_orbit\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_cylinder\",\n      \"title\": \"场景·气缸 / 汽缸\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·气缸 / 汽缸\\n\\n## 判据\\n题面或配图里出现「气缸」「汽缸」「封闭气体容器」这类东西时画这一件。\\n\\n## 布局\\n- 气缸是静态容器；活塞由 `piston` 元件卡画。\\n- 气体长度由活塞位置与缸底共同决定，不要各画一套。\\n\\n## 画法\\n- `Draw.box([0, 0.4], 0.24, 0.8);`\\n\\n## 这条场景最常错的地方\\n气缸跟着活塞动；缸底与活塞位置不联动。\\n\\n## 自检\\n- [ ] 气缸是静态基准，不读 `state`。\\n- [ ] 活塞与缸底共用同一套坐标。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 927,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.box([0, 0.4], 0.24, 0.8);\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"cylinder\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_gas_tube\",\n      \"title\": \"场景·玻璃管 / U形管\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·玻璃管 / U形管\\n\\n## 判据\\n题面或配图里出现「玻璃管」「U形管」「细管」这类东西时画这一件。\\n\\n## 布局\\n- 玻璃管是静态容器；水银柱由 `mercury` 元件卡画。\\n- 管口开/闭由场景给；管壁不要跟着液面动。\\n\\n## 画法\\n- `Draw.line([0, 0], [0, 1.2]);`\\n- `Draw.line([0.1, 0], [0.1, 1.2]);`\\n\\n## 这条场景最常错的地方\\n管口开/闭没区分；管壁跟着液面动。\\n\\n## 自检\\n- [ ] 管口开/闭与题面一致。\\n- [ ] 管壁是静态基准，不读 `state`。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 928,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.line([0, 0], [0, 1.2]);\\nDraw.line([0.1, 0], [0.1, 1.2]);\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"gas_tube\"\n      ]\n    },\n    {\n      \"id\": \"wb_el_piston\",\n      \"title\": \"元件·活塞\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 元件·活塞\\n\\n## 判据\\n题面或配图里出现「活塞」「注射器活塞」这类东西时画这一件；气缸由 `cylinder` 场景画。\\n\\n## 状态字段\\n- 用 `state.<key>.x / .y` 定活塞中心；尺寸自己定（米，可示意）。\\n- 不要写 `stateAt` / `VIEW` / `setup` / `readouts`。\\n\\n## 画法\\n- `Draw.box([state.piston_A.x, state.piston_A.y], 0.2, 0.04);`\\n\\n## 这条元件最常错的地方\\n活塞与气缸使用一套坐标；活塞的厚度可以自由裁量。\\n\\n## 自检\\n- [ ] 用 `state.<key>.x / .y` 定位置，与气缸共用同一套世界坐标；尺寸自己定。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\\n- [ ] 气缸由场景卡负责，活塞不重复画缸壁。\",\n      \"order\": 927,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.box([state.piston_A.x, state.piston_A.y], 0.2, 0.04);\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"piston\"\n      ],\n      \"size\": {\n        \"shape\": \"box\",\n        \"rotatable\": false\n      },\n      \"physical\": {\n        \"w\": 0.05,\n        \"h\": 0.02\n      }\n    },\n    {\n      \"id\": \"wb_el_mercury\",\n      \"title\": \"元件·水银柱（液面 A / 液面 B）\",\n      \"origin\": \"builtin\",\n      \"enabled\": false,\n      \"content\": \"# 元件·水银柱（液面 A / 液面 B）\\n\\n## 判据\\n题面或配图里出现「水银柱」「汞柱」这类东西时画这一件；玻璃管由 `gas_tube` 场景画。\\n\\n## 状态字段\\n- `state.<key>.yA` 与 `state.<key>.yB` 是两个液面的高度，由 `analysis` 分别算出。\\n- 只画两个液面之间的填充；管壁与裁剪由 `gas_tube` 场景负责。\\n\\n## 画法\\n- `Draw.polygon([[0, state.mercury_A.yA], [0.1, state.mercury_A.yA], [0.1, state.mercury_A.yB], [0, state.mercury_A.yB]], { fill: 'rgba(120,120,120,0.35)' });`\\n- `Draw.line([0, state.mercury_A.yA], [0.1, state.mercury_A.yA], { width: 2 });`\\n- `Draw.line([0, state.mercury_A.yB], [0.1, state.mercury_A.yB], { width: 2 });`\\n\\n## 这条元件最常错的地方\\n只画一个液面；把整根柱画成固定长度；液面越出管口。\\n\\n## 自检\\n- [ ] `yA` / `yB` 两个液面都由 analysis 给出。\\n- [ ] 只填充两液面之间，管壁归场景卡。\\n- [ ] 位置用物理米 `x/y`，尺寸用米，画布上不写字。\",\n      \"order\": 928,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.polygon([[0, state.mercury_A.yA], [0.1, state.mercury_A.yA], [0.1, state.mercury_A.yB], [0, state.mercury_A.yB]], { fill: 'rgba(120,120,120,0.35)' });\"\n      ],\n      \"kind\": \"element\",\n      \"constant\": false,\n      \"elements\": [\n        \"mercury\"\n      ],\n      \"size\": {\n        \"shape\": \"point\",\n        \"rotatable\": false\n      },\n      \"physical\": {\n        \"h\": 0.1\n      }\n    },\n    {\n      \"id\": \"wb_sc_wire\",\n      \"title\": \"场景·导线 / 电路布局\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·导线 / 电路布局\\n\\n## 判据\\n题面或配图里出现「电路」「导线」「电源」「开关」「电阻」「滑动变阻器」这类东西时画这一件；电表由 `meter` 场景画。\\n\\n## 布局\\n- 电路是静态布景：导线、电源、开关、电阻、变阻器都画在这里。\\n- 接线柱位置由场景给；电流方向用 `aux` 箭头，不用文字。\\n- 电表只画在 `meter` 场景，本卡不画表盘。\\n\\n## 画法\\n- `Draw.line([0, 0], [2, 0]);`\\n- `Draw.line([2, 0], [2, 1]);`\\n- `Draw.line([2, 1], [0, 1]);`\\n- `Draw.line([0, 1], [0, 0]);`\\n- `Draw.arrow([1.0, 0], [1, 0], { category: 'aux', mag: 1 });`\\n\\n## 这条场景最常错的地方\\n接线柱坐标每帧重算；电流方向画成电压方向；把电表表盘也画进导线场景。\\n\\n## 自检\\n- [ ] 电路是静态基准，不读 `state`。\\n- [ ] 电流方向用 `aux` 箭头，画布上不写字。\\n- [ ] 电表由 `meter` 场景负责，本卡不重复画。\",\n      \"order\": 912,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.line([0, 0], [2, 0]);\\nDraw.line([2, 0], [2, 1]);\\nDraw.line([2, 1], [0, 1]);\\nDraw.line([0, 1], [0, 0]);\\nDraw.arrow([1.0, 0], [1, 0], { category: 'aux', mag: 1 });\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"wire\"\n      ]\n    },\n    {\n      \"id\": \"wb_sc_meter\",\n      \"title\": \"场景·电表\",\n      \"origin\": \"builtin\",\n      \"enabled\": true,\n      \"content\": \"# 场景·电表\\n\\n## 判据\\n题面或配图里出现「电流表」「电压表」「多用电表」这类东西时画这一件。\\n\\n## 布局\\n- 电表是静态布景：圆表盘 + 指针；读数由 `readouts` 在画布外显示，画布上不写字。\\n- 表的位置由场景给，接线由 `wire` 场景负责。\\n\\n## 画法\\n- `Draw.circle([1.5, 0.8], 0.12);`\\n- `Draw.line([1.5, 0.8], [1.56, 0.86], { width: 2 });`\\n\\n## 这条场景最常错的地方\\n表盘上写数字/单位；把电表画成导线的一部分；接线柱没接进电路。\\n\\n## 自检\\n- [ ] 表盘不写字，读数在画布外。\\n- [ ] 电表位置固定，不读 `state`。\\n- [ ] 接线由 `wire` 场景负责。\",\n      \"order\": 913,\n      \"priority\": \"high\",\n      \"code_examples\": [\n        \"Draw.circle([1.5, 0.8], 0.12);\\nDraw.line([1.5, 0.8], [1.56, 0.86], { width: 2 });\"\n      ],\n      \"kind\": \"scene\",\n      \"constant\": false,\n      \"scenes\": [\n        \"meter\"\n      ]\n    }\n  ]\n}\n"}]};
